namespace sv_0b2f1b96431b42a4b597327f4d0c520e.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_0b2f1b96431b42a4b597327f4d0c520e.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
            </div>
        }
    </main>
</div>

@* ====== Profile Section ====== *@
@{
    RenderFragment ProfileSection = __builder2 =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-preview">
                @if (!string.IsNullOrEmpty(profileDisplayName))
                {
                    <img src="@profileAvatarUrl" alt="Avatar" class="avatar-img" />
                }
                <p class="avatar-url">@profileAvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="profileDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="profileEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="profileBio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };
}

@* ====== Notifications Section ====== *@
@{
    RenderFragment NotificationsSection = __builder2 =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="emailNotifications" />
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="pushNotifications" />
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="weeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channels-list">
                @if (allChannels != null)
                {
                    @foreach (var channel in allChannels)
                    {
                        <label class="channel-item">
                            <input type="checkbox" checked="@IsChannelMuted(channel)"
                                   @onchange="e => ToggleChannelMute(channel, (bool)(e.Value ?? false))" />
                            <span>@channel</span>
                        </label>
                    }
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };
}

@* ====== Security Section ====== *@
@{
    RenderFragment SecuritySection = __builder2 =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="TogglePasswordPanel">
                    <span>Change Password</span>
                    <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                </button>
                @if (showPasswordPanel)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="confirmPassword" />
                        </div>
                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-group tfa-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="twoFactorEnabled" />
                    <span>Two-Factor Authentication</span>
                </label>
                <span class="status-indicator @(twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>

            @if (lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @if (sessions != null)
                    {
                        @foreach (var session in sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != sessions.FirstOrDefault())
                                    {
                                        <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>

            @if (showRevokeConfirmation)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <h3>Revoke Session</h3>
                        <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="RevokeSession">Yes, Revoke</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* ====== Appearance Section ====== *@
@{
    RenderFragment AppearanceSection = __builder2 =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label><input type="radio" name="theme" value="Light" checked="@(selectedTheme == "Light")" @onchange='() => selectedTheme = "Light"' /> Light</label>
                    <label><input type="radio" name="theme" value="Dark" checked="@(selectedTheme == "Dark")" @onchange='() => selectedTheme = "Dark"' /> Dark</label>
                    <label><input type="radio" name="theme" value="System" checked="@(selectedTheme == "System")" @onchange='() => selectedTheme = "System"' /> System</label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label><input type="radio" name="fontSize" value="Small" checked="@(selectedFontSize == "Small")" @onchange='() => selectedFontSize = "Small"' /> Small</label>
                    <label><input type="radio" name="fontSize" value="Medium" checked="@(selectedFontSize == "Medium")" @onchange='() => selectedFontSize = "Medium"' /> Medium</label>
                    <label><input type="radio" name="fontSize" value="Large" checked="@(selectedFontSize == "Large")" @onchange='() => selectedFontSize = "Large"' /> Large</label>
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="selectedLanguage">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="compactMode" />
                    <span>Compact Mode</span>
                </label>
            </div>

            <h3>Preview</h3>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <button class="preview-button">Sample Button</button>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

@code {
    private string activeSection = "Profile";
    private bool isLoading;
    private string? toastMessage;
    private string toastType = "success";

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileAvatarUrl = "";
    private string profileBio = "";
    private UserProfile? savedProfile;

    // Notifications state
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<string> mutedChannels = new();
    private List<string> allChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };

    // Security state
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession>? sessions;
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance state
    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSection();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        await LoadSection();
    }

    private async Task LoadSection()
    {
        isLoading = true;
        StateHasChanged();

        try
        {
            switch (activeSection)
            {
                case "Profile":
                    var profile = await SettingsService.GetProfileAsync();
                    savedProfile = profile;
                    profileDisplayName = profile.DisplayName;
                    profileEmail = profile.Email;
                    profileAvatarUrl = profile.AvatarUrl;
                    profileBio = profile.Bio;
                    break;

                case "Notifications":
                    var prefs = await SettingsService.GetNotificationPrefsAsync();
                    emailNotifications = prefs.EmailNotifications;
                    pushNotifications = prefs.PushNotifications;
                    weeklyDigest = prefs.WeeklyDigest;
                    mutedChannels = new List<string>(prefs.MutedChannels);
                    break;

                case "Security":
                    var security = await SettingsService.GetSecuritySettingsAsync();
                    twoFactorEnabled = security.TwoFactorEnabled;
                    lastPasswordChange = security.LastPasswordChange;
                    sessions = security.Sessions;
                    break;

                case "Appearance":
                    var appearance = await SettingsService.GetAppearanceAsync();
                    selectedTheme = appearance.Theme;
                    selectedFontSize = appearance.FontSize;
                    selectedLanguage = appearance.Language;
                    compactMode = appearance.CompactMode;
                    break;
            }
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileAvatarUrl = savedProfile.AvatarUrl;
            profileBio = savedProfile.Bio;
        }
    }

    // Notifications methods
    private bool IsChannelMuted(string channel) => mutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!muted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task UpdatePassword()
    {
        if (newPassword != confirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
        showRevokeConfirmation = false;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            sessions?.Remove(sessionToRevoke);
            ShowToast($"Session on {sessionToRevoke.Device} revoked.", "success");
        }
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance methods
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{selectedTheme.ToLower()} preview-font-{selectedFontSize.ToLower()}";
        if (compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        StateHasChanged();
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

